schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/quit-day-job-trigger-contract.json",
  "title": "Quit day job trigger contract",
  "type": "object",
  "required": ["header", "trigger", "runway_co_condition", "gates", "reversal", "conclusion", "review"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "semver": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"},
    "share": {"type": "number", "minimum": 0, "maximum": 1},
    "money": {"type": "number", "exclusiveMinimum": 0}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "header": {
      "type": "object",
      "required": ["version", "committed_on", "post_hoc", "change_log"],
      "additionalProperties": false,
      "properties": {
        "version": {"$ref": "#/definitions/semver"},
        "committed_on": {"$ref": "#/definitions/date"},
        "post_hoc": {"type": "boolean"},
        "change_log": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["version", "date", "reason"],
            "additionalProperties": false,
            "properties": {
              "version": {"$ref": "#/definitions/semver"},
              "date": {"$ref": "#/definitions/date"},
              "reason": {"type": "string", "minLength": 5}
            }
          }
        }
      }
    },
    "trigger": {
      "type": "object",
      "required": ["metric", "provider", "report_name", "currency", "threshold", "consecutive_month_ends"],
      "additionalProperties": false,
      "properties": {
        "metric": {"const": "net_mrr"},
        "provider": {"type": "string", "enum": ["stripe_billing", "baremetrics", "chartmogul", "profitwell", "other_named_provider"]},
        "report_name": {"type": "string", "minLength": 3},
        "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
        "threshold": {"$ref": "#/definitions/money"},
        "consecutive_month_ends": {"type": "integer", "minimum": 3}
      }
    },
    "runway_co_condition": {
      "type": "object",
      "required": ["min_months", "savings", "monthly_burn", "burn_includes", "computed_on", "months"],
      "additionalProperties": false,
      "properties": {
        "min_months": {"type": "number", "exclusiveMinimum": 0},
        "savings": {"type": "number", "minimum": 0},
        "monthly_burn": {"$ref": "#/definitions/money"},
        "burn_includes": {
          "type": "array",
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["self_employment_tax", "health_insurance", "business_costs", "living_costs"]},
          "allOf": [{"contains": {"const": "self_employment_tax"}}, {"contains": {"const": "health_insurance"}}, {"contains": {"const": "business_costs"}}]
        },
        "computed_on": {"$ref": "#/definitions/date"},
        "months": {"type": "number", "minimum": 0}
      }
    },
    "gates": {
      "type": "object",
      "required": ["max_single_customer_share", "max_gross_mrr_churn_monthly"],
      "additionalProperties": false,
      "properties": {
        "max_single_customer_share": {"type": "number", "exclusiveMinimum": 0, "maximum": 1},
        "max_gross_mrr_churn_monthly": {"type": "number", "exclusiveMinimum": 0, "maximum": 1}
      }
    },
    "reversal": {
      "type": "object",
      "required": ["mrr_below", "consecutive_month_ends", "runway_below_months"],
      "additionalProperties": false,
      "properties": {
        "mrr_below": {"$ref": "#/definitions/money"},
        "consecutive_month_ends": {"type": "integer", "minimum": 2},
        "runway_below_months": {"type": "number", "exclusiveMinimum": 0}
      }
    },
    "conclusion": {
      "type": "object",
      "required": ["statement", "action", "date_rule", "notice_period_days", "inform_order", "evidence_links"],
      "additionalProperties": false,
      "properties": {
        "statement": {"type": "string", "minLength": 40, "not": {"pattern": "(?i)when ready|when it feels right|when needed"}},
        "action": {"type": "string", "enum": ["resign", "reduce_to_part_time"]},
        "date_rule": {"type": "string", "minLength": 20},
        "notice_period_days": {"type": "integer", "minimum": 0},
        "inform_order": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 3}},
        "evidence_links": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["url", "kind", "covers_month_end"],
            "additionalProperties": false,
            "properties": {
              "url": {"type": "string", "pattern": "^(https?://|repo:|file:)"},
              "kind": {"type": "string", "enum": ["provider_mrr_report", "provider_export", "runway_model"]},
              "covers_month_end": {"$ref": "#/definitions/date"}
            }
          }
        }
      }
    },
    "review": {
      "type": "object",
      "required": ["cadence", "last_run_at", "entries"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"type": "string", "enum": ["monthly", "quarterly"]},
        "last_run_at": {"$ref": "#/definitions/date"},
        "entries": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["run_at", "readings", "runway_months", "top_customer_share", "gross_churn_monthly", "verdict"],
            "additionalProperties": false,
            "properties": {
              "run_at": {"$ref": "#/definitions/date"},
              "readings": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "object",
                  "required": ["month_end", "net_mrr"],
                  "additionalProperties": false,
                  "properties": {
                    "month_end": {"$ref": "#/definitions/date"},
                    "net_mrr": {"type": "number", "minimum": 0}
                  }
                }
              },
              "runway_months": {"type": "number", "minimum": 0},
              "top_customer_share": {"$ref": "#/definitions/share"},
              "gross_churn_monthly": {"$ref": "#/definitions/share"},
              "verdict": {"type": "string", "enum": ["not_fired", "window_in_progress", "fired", "reversal_triggered"]},
              "window_count": {"type": "integer", "minimum": 1}
            },
            "if": {"properties": {"verdict": {"const": "window_in_progress"}}},
            "then": {"required": ["window_count"]}
          }
        }
      }
    }
  }
}

example.code:
{
  "header": {
    "version": "1.0.0",
    "committed_on": "2026-02-01",
    "post_hoc": false,
    "change_log": [{"version": "1.0.0", "date": "2026-02-01", "reason": "initial contract, committed before any qualifying month-end"}]
  },
  "trigger": {"metric": "net_mrr", "provider": "stripe_billing", "report_name": "Stripe Billing MRR report", "currency": "USD", "threshold": 4000, "consecutive_month_ends": 3},
  "runway_co_condition": {"min_months": 12, "savings": 40600, "monthly_burn": 3100, "burn_includes": ["living_costs", "self_employment_tax", "health_insurance", "business_costs"], "computed_on": "2026-08-31", "months": 13.1},
  "gates": {"max_single_customer_share": 0.2, "max_gross_mrr_churn_monthly": 0.05},
  "reversal": {"mrr_below": 3000, "consecutive_month_ends": 2, "runway_below_months": 6},
  "conclusion": {
    "statement": "Resign effective the first of the month after the third consecutive month-end at or above 4,000 USD net MRR with runway at or above 12 months and both gates inside their limits; give 30 days notice; tell my partner first, then my manager, then customers.",
    "action": "resign",
    "date_rule": "effective the first of the month after the third qualifying month-end",
    "notice_period_days": 30,
    "inform_order": ["partner", "manager", "customers"],
    "evidence_links": [
      {"url": "https://dashboard.stripe.com/billing/reports/mrr", "kind": "provider_mrr_report", "covers_month_end": "2026-08-31"},
      {"url": "repo:finance/runway-model-2026-Q3.xlsx", "kind": "runway_model", "covers_month_end": "2026-08-31"}
    ]
  },
  "review": {
    "cadence": "quarterly",
    "last_run_at": "2026-09-01",
    "entries": [
      {"run_at": "2026-06-01", "readings": [{"month_end": "2026-03-31", "net_mrr": 3480}, {"month_end": "2026-04-30", "net_mrr": 3720}, {"month_end": "2026-05-31", "net_mrr": 3910}], "runway_months": 12.4, "top_customer_share": 0.12, "gross_churn_monthly": 0.031, "verdict": "not_fired"},
      {"run_at": "2026-09-01", "readings": [{"month_end": "2026-06-30", "net_mrr": 4150}, {"month_end": "2026-07-31", "net_mrr": 4300}, {"month_end": "2026-08-31", "net_mrr": 4420}], "runway_months": 13.1, "top_customer_share": 0.11, "gross_churn_monthly": 0.028, "verdict": "fired"}
    ]
  }
}

{
  "header": {
    "version": "1.0.0",
    "committed_on": "2026-07-03",
    "post_hoc": false,
    "change_log": [{"version": "1.0.0", "date": "2026-07-03", "reason": "wrote it up after the big month"}]
  },
  "trigger": {"metric": "gross_cash", "provider": "spreadsheet", "report_name": "my sheet", "currency": "USD", "threshold": 4000, "consecutive_month_ends": 1},
  "runway_co_condition": {"min_months": 12, "savings": 18000, "monthly_burn": 1500, "burn_includes": ["living_costs"], "computed_on": "2026-07-03", "months": 12},
  "gates": {"max_single_customer_share": 1, "max_gross_mrr_churn_monthly": 1},
  "reversal": {"mrr_below": 4000, "consecutive_month_ends": 1, "runway_below_months": 0},
  "conclusion": {
    "statement": "Quit when ready.",
    "action": "resign",
    "date_rule": "soon",
    "notice_period_days": 0,
    "inform_order": [],
    "evidence_links": [{"url": "screenshot.png", "kind": "spreadsheet_screenshot", "covers_month_end": "2026-06-30"}]
  },
  "review": {
    "cadence": "quarterly",
    "last_run_at": "2026-09-01",
    "entries": [
      {"run_at": "2026-09-01", "readings": [], "runway_months": 12, "top_customer_share": 0.71, "gross_churn_monthly": 0.09, "verdict": "fired"}
    ]
  }
}
